// client/src/components/RouletteWheel.jsx

import React, { useRef, useEffect, useState } from 'react';

// 💡 룰렛 보상 목록 데이터를 부모(Roulette.jsx)로부터 받습니다.
// 룰렛 UI를 구현하기 위해 필요한 최소한의 props만 사용합니다.

/**
 * SVG 기반 룰렛 휠 구현
 * @param {Array} rewards - 백엔드에서 가져온 룰렛 보상 목록 (name, probability, type 등 포함)
 * @param {boolean} isSpinning - 룰렛 회전 상태
 * @param {object} spinResult - 서버에서 받은 최종 결과 객체 { reward, coupon, message }
 * @param {number} rotationAngle - 룰렛을 멈출 최종 각도
 */
function RouletteWheel({ rewards, isSpinning, spinResult, rotationAngle }) {
    
    const wheelRef = useRef(null);
    const [segments, setSegments] = useState([]);

    // --- 1. 유틸리티 함수 ---
    function degToRad(d) { return (d * Math.PI) / 180; }
    
    // --- 2. 보상 데이터를 SVG 세그먼트 데이터로 변환 ---
    useEffect(() => {
        // 백엔드의 rewards 배열을 UI 세그먼트로 사용
        if (rewards && rewards.length > 0) {
            setSegments(rewards.map(r => ({ 
                label: r.name, 
                key: r.name, // name을 고유 키로 사용
                type: r.type,
                // UI 스타일링을 위해 확률에 따른 색상 정의 (선택 사항)
            })));
        }
    }, [rewards]);
    
    // --- 3. 애니메이션 및 회전 처리 ---
    // 애니메이션 관리: isSpinning=true일 때는 CSS 무한회전 클래스를 적용하고,
    // isSpinning가 false로 변경되면 최종 rotationAngle로 서서히 멈춥니다.
    useEffect(() => {
        const wheel = wheelRef.current;
        if (!wheel || segments.length === 0) return;

        if (isSpinning) {
            // 무한 회전(빠르게 돔)
            wheel.classList.add('spinning');
            // 초기 transform을 그대로 두고 CSS 애니메이션에 맡깁니다.
            wheel.style.transition = '';
        } else {
            // 멈추는 애니메이션: spinning 클래스 제거 후 transform으로 회전 각도 적용
            wheel.classList.remove('spinning');
            // 4초 동안 완만하게 멈추도록 transition 적용
            wheel.style.transition = 'transform 4s cubic-bezier(.12,.7,.12,1)';
            wheel.style.transform = `rotate(${rotationAngle}deg)`;
        }
    }, [isSpinning, rotationAngle, segments.length]);


    // --- 4. SVG 렌더링 설정 ---
    if (segments.length === 0) {
        return <div className="text-center p-8 text-gray-500">룰렛 데이터 로드 중...</div>;
    }
    
    const radius = 140;
    const center = radius + 4; // SVG 중앙 좌표

    return (
        <div className="wheel-container" style={{ padding: 20 }}>
            <div className="wheel-wrapper card">
                <div className={`wheel-rotator ${isSpinning ? 'spinning' : ''}`} ref={wheelRef} style={{ transformOrigin: 'center center' }}>
                    <svg width={(radius * 2) + 8} height={(radius * 2) + 8} viewBox={`0 0 ${center * 2} ${center * 2}`}>
                        {/* translate to center inside the svg so segment coords are relative */}
                        <g transform={`translate(${center},${center})`}>
                        {segments.map((seg, i) => {
                            const angle = 360 / segments.length;
                            const start = i * angle;
                            const largeArc = angle > 180 ? 1 : 0;
                            
                            // 세그먼트의 색상 설정
                            let fill;
                            if (seg.type === 'POINTS') fill = '#e0f7fa'; // 포인트
                            else if (seg.type === 'COUPON') fill = '#ffecb3'; // 쿠폰
                            else fill = '#f5f5f5'; // 꽝/NONE

                            // Path D 속성 계산 (M 0 0 L x1 y1 A r r 0 largeArc 1 x2 y2 Z)
                            const path = `M ${0} ${0} L ${radius * Math.cos(degToRad(start))} ${radius * Math.sin(degToRad(start))} A ${radius} ${radius} 0 ${largeArc} 1 ${radius * Math.cos(degToRad(start + angle))} ${radius * Math.sin(degToRad(start + angle))} Z`;
                            
                            // 텍스트 위치 계산
                            const textAngle = start + angle / 2;
                            const textX = (radius / 1.5) * Math.cos(degToRad(textAngle));
                            const textY = (radius / 1.5) * Math.sin(degToRad(textAngle));

                            return (
                                <g key={seg.key + i}>
                                    <path d={path} fill={fill} stroke="#ddd" />
                                    <text 
                                        x={textX} 
                                        y={textY} 
                                        fill="#333" 
                                        fontSize={10} 
                                        textAnchor="middle" 
                                        alignmentBaseline="middle" 
                                        transform={`rotate(${textAngle} ${textX} ${textY})`} // 텍스트 회전
                                    >
                                        {seg.label}
                                    </text>
                                </g>
                            );
                        })}
                        </g>
                    </svg>

                    {/* 포인터 (지시계) */}
                    <div className="pointer bounce" style={{ position: 'absolute', left: '50%', top: -6, transform: 'translateX(-50%)', width: 0, height: 0, borderLeft: '12px solid transparent', borderRight: '12px solid transparent', borderBottom: '18px solid #ff5252' }} />
                </div>
            </div>
        </div>
    );
}

export default RouletteWheel;
